    /// A trade a tenth of a second after the last, one unit at a walking
    /// price, so bars carry distinct times and a readable price range.
    fn trade(agg_id: u64) -> quantick_engine::Trade {
        quantick_engine::Trade {
            agg_id,
            timestamp_ms: 1_000 + agg_id as i64 * 100,
            price: Decimal::from(100) + Decimal::new(agg_id as i64 % 20, 1),
            quantity: Decimal::ONE,
            side: if agg_id.is_multiple_of(2) {
                quantick_engine::Side::Buy
            } else {
                quantick_engine::Side::Sell
            },
        }
    }

    /// Paper trading through the app's own event path: backfill only seeds
    /// (never fills), the toolbar buy queues, the next live print fills, and
    /// the status-bar cell reports the simulated position.
    #[test]
    fn a_simulated_buy_fills_from_the_next_live_print_only() {
        let (mut app, evt_tx, _cmd_rx, _book_tx) = test_app();
        evt_tx
            .try_send(FeedEvent::Backfilled(vec![trade(2)]))
            .unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        assert!(app.active_tab().paper.ready(), "backfill seeds the mark");
        assert!(
            app.active_tab().paper.status_cell().is_none(),
            "an untouched simulator owes no status line"
        );

        app.apply_toolbar_action(ToolbarAction::PaperBuy);
        assert!(
            app.active_tab().paper.status_cell().is_some(),
            "a queued market order is visible state"
        );
        evt_tx.try_send(FeedEvent::Live(trade(4))).unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        let (text, _) = app
            .active_tab()
            .paper
            .status_cell()
            .expect("the fill opened a position");
        assert!(
            text.starts_with("SIM"),
            "the cell is labeled simulated: {text}"
        );
        assert!(
            app.status_model().sim_pnl.is_some(),
            "the status bar model carries the cell"
        );
    }

    /// The toolbar's exit control end to end: with a position open the model
    /// grows the ✕ button, the close action queues, the next print fills it,
    /// and the status cell switches from naming the position to `flat`.
    #[test]
    fn the_toolbar_close_action_exits_the_open_position() {
        let (mut app, evt_tx, _cmd_rx, _book_tx) = test_app();
        // The close journals; without this the test writes a real
        // `paper-trades/` folder into the crate's source tree.
        let dir =
            std::env::temp_dir().join(format!("quantick-paper-app-close-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        app.active_tab_mut().paper.redirect_history_dir(dir.clone());
        evt_tx
            .try_send(FeedEvent::Backfilled(vec![trade(2)]))
            .unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        app.apply_toolbar_action(ToolbarAction::PaperBuy);
        evt_tx.try_send(FeedEvent::Live(trade(4))).unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        let (text, _) = app.active_tab().paper.status_cell().expect("open");
        assert!(text.contains("LONG"), "the cell names the side: {text}");
        assert!(
            app.active_tab().paper.close_button_label().is_some(),
            "an open position grows the toolbar exit"
        );

        app.apply_toolbar_action(ToolbarAction::PaperClose);
        evt_tx.try_send(FeedEvent::Live(trade(6))).unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        assert!(
            app.active_tab().paper.position_summary().is_none(),
            "the close filled at the next print"
        );
        let (text, _) = app.active_tab().paper.status_cell().expect("history");
        assert!(text.contains("flat"), "the cell says flat: {text}");
        assert!(
            app.active_tab().paper.close_button_label().is_none(),
            "flat removes the toolbar exit"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A source reset (replay seek, feed switch) flattens the simulated
    /// position at the last mark and journals the round trip — the same
    /// honesty contract the drawings' clear follows.
    #[test]
    fn a_source_reset_flattens_the_simulated_position_and_journals_it() {
        let (mut app, evt_tx, _cmd_rx, _book_tx) = test_app();
        let dir =
            std::env::temp_dir().join(format!("quantick-paper-app-reset-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        app.active_tab_mut().paper.redirect_history_dir(dir.clone());
        // No `set_symbol` here: the tab's own drain syncs the journal to its
        // symbol before reading a single event, which is what makes the
        // folder assertion below a proof of that wiring too.
        evt_tx
            .try_send(FeedEvent::Backfilled(vec![trade(2)]))
            .unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        app.apply_toolbar_action(ToolbarAction::PaperBuy);
        evt_tx.try_send(FeedEvent::Live(trade(4))).unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);

        evt_tx.try_send(FeedEvent::Reset).unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        assert!(
            app.active_tab().paper.status_cell().is_some(),
            "the realized history keeps the cell alive"
        );
        let files: Vec<_> = std::fs::read_dir(dir.join("TESTUSDT"))
            .expect("the flatten was journaled under the symbol's folder")
            .flatten()
            .collect();
        assert_eq!(files.len(), 1, "one session, one history file");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn quiet_market_keeps_the_observed_arrival_latency_live() {
        let (mut app, _evt_tx, _cmd_rx, _book_tx) = test_app();
        app.active_tab_mut().feed_connection = FeedConnectionState::Connected;
        let trade = trade(1);
        let received_at_ms = trade.timestamp_ms + 42;

        app.active_tab_mut()
            .ingest_live_trade_at(&trade, received_at_ms);

        assert_eq!(app.active_tab().trade_arrival_ms(), Some(42));
        assert_eq!(
            statusbar::feed_state(false, app.active_tab().feed_connection),
            statusbar::FeedState::Live
        );
        assert_eq!(
            app.active_tab().trade_arrival_ms(),
            Some(42),
            "reading the status again without another print must not age latency"
        );
    }

    /// The gap the removed `Stalled` state used to cover: a transport that
    /// stays open and stops delivering. No error, no disconnect, and the
    /// stored arrival figure never ages — only the tape's own age does.
    #[test]
    fn a_quiet_tape_reads_as_stale_while_arrival_stays_frozen() {
        let (mut app, _evt_tx, _cmd_rx, _book_tx) = test_app();
        app.active_tab_mut().feed_connection = FeedConnectionState::Connected;
        let trade = trade(1);
        app.active_tab_mut()
            .ingest_live_trade_at(&trade, trade.timestamp_ms + 42);

        // A moment later: fresh.
        let age = app
            .active_tab()
            .tape_age_at(trade.timestamp_ms + 500)
            .expect("a live tape has an age");
        assert!(age < metrics::STALE_TAPE_MS);
        assert_eq!(
            statusbar::tape_text(None, app.active_tab().trade_arrival_ms(), Some(age)),
            "arrival 42 ms"
        );

        // A minute of silence on the same open socket.
        let age = app
            .active_tab()
            .tape_age_at(trade.timestamp_ms + 60_000)
            .expect("still a tape, just an old one");
        assert!(age > metrics::STALE_TAPE_MS, "{age} ms");
        assert_eq!(
            app.active_tab().trade_arrival_ms(),
            Some(42),
            "the arrival observation is frozen, which is why it cannot report this"
        );
        assert_eq!(
            statusbar::tape_text(None, app.active_tab().trade_arrival_ms(), Some(age)),
            "stale 60 s"
        );
    }

    #[test]
    fn backfill_does_not_claim_a_live_transport_latency() {
        let (mut app, evt_tx, _cmd_rx, _book_tx) = test_app();
        evt_tx
            .try_send(FeedEvent::Backfilled(vec![trade(1)]))
            .unwrap();

        app.active_tab_mut().drain_feed();

        assert_eq!(app.active_tab().trade_arrival_ms(), None);
        assert_eq!(
            statusbar::feed_state(false, app.active_tab().feed_connection),
            statusbar::FeedState::Connecting
        );
    }

    #[test]
    fn one_ui_drain_uses_one_observation_for_single_and_batched_trades() {
        use std::cell::Cell;

        let (mut app, evt_tx, _cmd_rx, _book_tx) = test_app();
        let last_trade = trade(3);
        let received_at_ms = last_trade.timestamp_ms + 75;
        evt_tx.try_send(FeedEvent::Live(trade(1))).unwrap();
        evt_tx
            .try_send(FeedEvent::LiveBatch(vec![trade(2), last_trade]))
            .unwrap();
        let clock_calls = Cell::new(0_u32);

        app.active_tab_mut().drain_feed_with_clock(|| {
            clock_calls.set(clock_calls.get() + 1);
            received_at_ms
        });

        assert_eq!(clock_calls.get(), 1, "one wall-clock read per UI drain");
        // Per market. The window's own summary counter adds these up across
        // every tab, in `drain_tabs`.
        assert_eq!(app.active_tab().live_trades, 3);
        assert_eq!(app.active_tab().trade_arrival_ms(), Some(75));
        assert_eq!(app.active_tab().flow_pane.state.timeline_revision(), 3);
        assert_eq!(
            app.active_tab()
                .flow_pane
                .state
                .partial()
                .map(|bar| bar.trade_count),
            Some(3)
        );
    }

    #[test]
    fn one_book_drain_uses_one_clock_observation() {
        use std::cell::Cell;

        let (mut app, _evt_tx, _cmd_rx, book_tx) = test_app();
        for _ in 0..2 {
            book_tx
                .try_send(DepthEvent::Status {
                    symbol: "TESTUSDT".to_owned(),
                    generation: 1,
                    status: quantick_orderbook::DepthStatus::Connecting,
                })
                .unwrap();
        }
        let clock_calls = Cell::new(0_u32);

        app.active_tab_mut().drain_book_feed_with_clock(|| {
            clock_calls.set(clock_calls.get() + 1);
            10_000
        });

        assert_eq!(clock_calls.get(), 1, "one wall-clock read per UI drain");
    }

    /// An app holding `count` backfilled trades, built into tick(1) bars — one
    /// bar per trade, the finest series a spec change can coarsen.
    fn app_with_history(count: u64) -> (QuantickApp, mpsc::Receiver<FeedCommand>) {
        let (mut app, evt_tx, cmd_rx, _book_tx) = test_app();
        app.active_tab_mut().flow_pane.tick_n = 1;
        app.active_tab_mut().apply_spec_changes();
        app.active_tab_mut().apply_spec_changes();
        let trades: Vec<_> = (1..=count).map(trade).collect();
        evt_tx.try_send(FeedEvent::Backfilled(trades)).unwrap();
        app.active_tab_mut().drain_feed();
        assert_eq!(app.active_tab().flow_pane.state.bars().len() as u64, count);
        (app, cmd_rx)
    }

    /// An app whose source quotes prices and nothing else: no book, no traded
    /// volume — what a live CFD bridge publishes.
    fn app_without_depth() -> (QuantickApp, mpsc::Receiver<FeedCommand>) {
        let (_evt_tx, evt_rx) = mpsc::channel(64);
        let (_book_tx, book_rx) = mpsc::channel(64);
        let (cmd_tx, cmd_rx) = mpsc::channel(16);
        let app = QuantickApp::new(
            test_config(),
            "binance",
            "TESTUSDT",
            BarSpec::Tick(50),
            FeedHandle {
                events: evt_rx,
                book_events: book_rx,
                notices: feed::silent_notices(),
                capabilities: feed::fixed_capabilities(FeedCapabilities::none()),
                commands: cmd_tx,
                replay: None,
            },
        );
        (app, cmd_rx)
    }

    /// How many switches each pane's menu lays out at its top level. The two
    /// menus split one list ([`ChartLayer::on_tape`]), so counting either from
    /// the list is what keeps a new layer from silently landing on the wrong
    /// canvas's menu.
    fn chart_menu_entries() -> usize {
        ChartLayer::ALL
            .into_iter()
            .filter(|layer| !layer.on_tape())
            .count()
    }

    fn tape_menu_entries() -> usize {
        ChartLayer::ALL
            .into_iter()
            .filter(|layer| layer.on_tape())
            .count()
    }

    /// The active tab's flow pane beside the chrome a canvas frame hands it.
    fn with_flow_pane<R>(
        app: &mut QuantickApp,
        body: impl FnOnce(&mut ChartPane, &mut pane::PaneChrome<'_>) -> R,
    ) -> R {
        let capabilities = app.active_tab().capabilities(&app.config);
        let side_inferred = app.active_tab().side_note(&app.config).is_some();
        let QuantickApp {
            tabs,
            active_tab,
            toolrail,
            drawing_presets,
            pending_text_edit,
            style,
            tz,
            layer_actions,
            footprint_config,
            ..
        } = app;
        let tab = &mut tabs[*active_tab];
        let mut chrome = pane::PaneChrome {
            toolrail,
            presets: drawing_presets,
            begin_text_edit: pending_text_edit,
            style,
            tz: *tz,
            symbol: &tab.symbol,
            paper: &mut tab.paper,
            paper_owns_input: true,
            // One pane in hand and no tab around it: there is no other pane
            // whose shared marks could be under the pointer.
            shared_pick: None,
            shared: pane::SharedInteraction::default(),
            capabilities,
            side_inferred,
            footprint: footprint_config,
            layers: layer_actions,
        };
        body(&mut tab.flow_pane, &mut chrome)
    }

    /// Switch a layer exactly as the menu does, including the hop the app makes
    /// for the ones a pane does not own.
    fn switch_layer(app: &mut QuantickApp, layer: ChartLayer, visible: bool) {
        with_flow_pane(app, |pane, chrome| {
            pane.set_layer_visible(layer, visible, chrome.layers);
        });
        app.apply_layer_actions();
    }

    /// Whether the active tab's flow pane is painting `layer`.
    fn layer_on(app: &QuantickApp, layer: ChartLayer) -> bool {
        app.active_tab().flow_pane.layer_visible(layer, &app.style)
    }

    /// The layer menu writes through to whoever owns the layer, and touches
    /// nothing else. A menu holding its own copy of "is the heatmap on" would
    /// disagree with the toolbar the moment either one was used.
    #[test]
    fn each_layer_switch_moves_exactly_one_owner() {
        let (mut app, _events, _commands, _book) = test_app();
        // What the chart opens with: the market layers are opt-in, the chart's
        // own chrome is on. This is the state the file's absence must preserve.
        for (layer, expected) in [
            (ChartLayer::Heatmap, false),
            (ChartLayer::Bubbles, false),
            // The footprint is opt-in like every market layer: the chart must
            // open pixel-identical to the day before the layer existed.
            (ChartLayer::Footprint, false),
            (ChartLayer::LiveStrip, false),
            (ChartLayer::LaneMarks, true),
            (ChartLayer::DepthGaps, true),
            (ChartLayer::Grid, true),
            (ChartLayer::LastPrice, true),
            // A full-height rule across the candles for a boundary read once:
            // opt-in, like the market layers above it.
            (ChartLayer::BackfillDivider, false),
            (ChartLayer::SeamDivider, true),
            (ChartLayer::Crosshair, true),
            (ChartLayer::PaperTrading, true),
            (ChartLayer::Drawings, true),
        ] {
            assert_eq!(
                layer_on(&app, layer),
                expected,
                "{} opens in the wrong state",
                layer.id()
            );
        }

        for layer in ChartLayer::ALL {
            let before: Vec<bool> = ChartLayer::ALL
                .into_iter()
                .map(|other| layer_on(&app, other))
                .collect();
            let flipped = !layer_on(&app, layer);
            switch_layer(&mut app, layer, flipped);
            for (other, was) in ChartLayer::ALL.into_iter().zip(before) {
                let expected = if other == layer { flipped } else { was };
                assert_eq!(
                    layer_on(&app, other),
                    expected,
                    "switching {} moved {} too",
                    layer.id(),
                    other.id()
                );
            }
            switch_layer(&mut app, layer, !flipped);
        }
    }

    /// Hiding is a view state, never a kill switch: the recorder keeps running
    /// behind a hidden heatmap, so unhiding repaints the retained past instead
    /// of opening a hole in it.
    #[test]
    fn hiding_a_layer_never_stops_the_data_behind_it() {
        let (mut app, _events, _commands, _book) = test_app();
        let config = app.config.clone();
        app.active_tab_mut().ensure_book_capture(&config);
        assert!(
            app.active_tab().tape().enabled(),
            "capture is on before the test"
        );

        switch_layer(&mut app, ChartLayer::Heatmap, true);
        assert!(layer_on(&app, ChartLayer::Heatmap));
        switch_layer(&mut app, ChartLayer::Heatmap, false);
        assert!(!layer_on(&app, ChartLayer::Heatmap));
        assert!(
            app.active_tab().tape().enabled(),
            "the map went off screen; the recording must not stop with it"
        );

        // Same for the drawings: the layer switch hides them, it never removes
        // them, and the objects come back with their anchors intact.
        let before = app.active_tab().flow_pane.drawings.items().len();
        switch_layer(&mut app, ChartLayer::Drawings, false);
        assert_eq!(
            app.active_tab().flow_pane.drawings.items().len(),
            before,
            "hiding deletes nothing"
        );
        switch_layer(&mut app, ChartLayer::Drawings, true);
        assert!(layer_on(&app, ChartLayer::Drawings));
    }

    /// Close the app with layers hidden, open it again, and the canvas comes
    /// back the way it was left — through the same restore the constructor runs.
    #[test]
    fn layer_visibility_survives_a_restart() {
        let dir = std::env::temp_dir().join(format!("quantick-app-layers-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("scratch dir");
        let path = dir.join("chart-layers.toml");
        let _ = std::fs::remove_file(&path);

        let (mut app, _events, _commands, _book) = test_app();
        app.chart_layers_path = path.clone();
        app.saved_layer_mask = app.layer_mask();
        switch_layer(&mut app, ChartLayer::Crosshair, false);
        switch_layer(&mut app, ChartLayer::PaperTrading, false);
        switch_layer(&mut app, ChartLayer::Grid, false);
        // Switched through the toolbar's own action rather than the menu: the
        // save must follow the state, not the widget that moved it.
        app.apply_toolbar_action(ToolbarAction::SetHeatmap(true));
        // A market layer switched *on* has to come back on, which is why the
        // file records each layer's state instead of a list of hidden ones.
        switch_layer(&mut app, ChartLayer::Bubbles, true);
        // The tape's three: this file is their only home (the order-flow preset
        // refuses to carry a switch), so without them the tape would open on
        // its defaults every single launch.
        switch_layer(&mut app, ChartLayer::TapeHeatmap, false);
        switch_layer(&mut app, ChartLayer::TapeChart, false);
        app.maintain_chart_layers();
        assert_eq!(
            app.saved_layer_mask,
            app.layer_mask(),
            "a settled canvas writes nothing further"
        );

        let (mut restored, _events, _commands, _book) = test_app();
        restored.chart_layers_path = path.clone();
        restored.restore_chart_layers();
        for (layer, expected) in [
            (ChartLayer::Crosshair, false),
            (ChartLayer::PaperTrading, false),
            (ChartLayer::Grid, false),
            (ChartLayer::Heatmap, true),
            (ChartLayer::Bubbles, true),
            (ChartLayer::LastPrice, true),
            (ChartLayer::Drawings, true),
            // Off, and its layer switch off under it — a tape put back on the
            // canvas has to be the tape that was taken off it, across a
            // restart as much as across a click.
            (ChartLayer::TapeChart, false),
            (ChartLayer::TapeHeatmap, false),
            (ChartLayer::TapeBubbles, true),
        ] {
            assert_eq!(
                layer_on(&restored, layer),
                expected,
                "{} did not survive the restart",
                layer.id()
            );
        }
        // The lane marks belong to the order-flow preset; this file must not
        // have taken a second opinion on them.
        let text = std::fs::read_to_string(&path).expect("state file");
        assert!(!text.contains("lane_marks"), "{text}");
        std::fs::remove_file(&path).ok();
    }

    /// A tab opened later shows the same canvas as the one beside it: opening a
    /// second market is not a request to bring back hidden chrome.
    #[test]
    fn a_new_tab_opens_on_the_layers_the_user_left_showing() {
        let dir = std::env::temp_dir().join(format!("quantick-app-newtab-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("scratch dir");
        let path = dir.join("chart-layers.toml");
        let _ = std::fs::remove_file(&path);

        let (mut app, _events, _commands, _book) = test_app();
        app.chart_layers_path = path.clone();
        app.saved_layer_mask = app.layer_mask();
        switch_layer(&mut app, ChartLayer::Crosshair, false);
        app.maintain_chart_layers();
        // A fresh app reads the file, then opens a second market.
        let (mut restored, _events, _commands, _book) = test_app();
        restored.chart_layers_path = path.clone();
        restored.restore_chart_layers();
        let (_evt_tx, evt_rx) = mpsc::channel(4);
        let (_book_tx, book_rx) = mpsc::channel(4);
        let (cmd_tx, _cmd_rx) = mpsc::channel(4);
        restored.adopt_tab(
            "binance".to_owned(),
            "OTHERUSDT".to_owned(),
            FeedHandle {
                events: evt_rx,
                book_events: book_rx,
                notices: feed::silent_notices(),
                capabilities: feed::fixed_capabilities(ProviderKind::Binance.capabilities()),
                commands: cmd_tx,
                replay: None,
            },
            None,
        );
        assert_eq!(restored.tabs.len(), 2, "the second market opened");
        assert!(
            !layer_on(&restored, ChartLayer::Crosshair),
            "the new tab brought back a layer the user had switched off"
        );
        std::fs::remove_file(&path).ok();
    }

    /// The menu itself: every layer gets a switch, a layer the feed cannot
    /// produce is offered disabled rather than as a lie, and clicking a real
    /// checkbox hides the layer behind it.
    #[test]
    fn the_layer_menu_offers_every_layer_and_its_switches_work() {
        let dir = std::env::temp_dir().join(format!("quantick-app-menu-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("scratch dir");
        let path = dir.join("chart-layers.toml");
        let _ = std::fs::remove_file(&path);

        let ctx = egui::Context::default();
        let screen = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(400.0, 700.0));
        let (mut app, _events, _commands, _book) = test_app();
        app.chart_layers_path = path.clone();

        let menu_frame = |app: &mut QuantickApp, events: Vec<egui::Event>| {
            with_flow_pane(app, |pane, chrome| {
                let _ = ctx.run(
                    egui::RawInput {
                        screen_rect: Some(screen),
                        events,
                        ..Default::default()
                    },
                    |ctx| {
                        egui::CentralPanel::default()
                            .show(ctx, |ui| pane.draw_layer_menu(ui, chrome));
                    },
                );
            });
        };

        menu_frame(&mut app, Vec::new());
        assert_eq!(
            app.active_tab().flow_pane.layer_menu_rects.len(),
            chart_menu_entries(),
            "every layer needs a switch, or it cannot be turned off at all"
        );
        assert!(
            app.active_tab()
                .flow_pane
                .layer_menu_rects
                .iter()
                .all(|(layer, _)| !layer.on_tape()),
            "and the candles' menu never offers a switch for the canvas beside it"
        );

        let crosshair = app
            .active_tab()
            .flow_pane
            .layer_menu_rects
            .iter()
            .find(|(layer, _)| *layer == ChartLayer::Crosshair)
            .expect("the crosshair has a switch")
            .1
            .center();
        assert!(layer_on(&app, ChartLayer::Crosshair));
        menu_frame(
            &mut app,
            vec![
                egui::Event::PointerMoved(crosshair),
                egui::Event::PointerButton {
                    pos: crosshair,
                    button: egui::PointerButton::Primary,
                    pressed: true,
                    modifiers: egui::Modifiers::default(),
                },
            ],
        );
        menu_frame(
            &mut app,
            vec![egui::Event::PointerButton {
                pos: crosshair,
                button: egui::PointerButton::Primary,
                pressed: false,
                modifiers: egui::Modifiers::default(),
            }],
        );
        assert!(
            !layer_on(&app, ChartLayer::Crosshair),
            "clicking the switch has to switch the layer"
        );

        // A capability the source lacks is disabled, not silently absent: a
        // recording has no book, and the entry says so instead of offering a
        // switch that would do nothing.
        let full = app.active_tab().capabilities(&app.config);
        let pane = &app.active_tab().flow_pane;
        assert!(pane.layer_blocked(ChartLayer::Heatmap, full).is_none());
        let (mut quote_only, _commands) = app_without_depth();
        let quotes = quote_only.active_tab().capabilities(&quote_only.config);
        let pane = &quote_only.active_tab().flow_pane;
        assert!(
            pane.layer_blocked(ChartLayer::Heatmap, quotes).is_some(),
            "a source with no book cannot promise a heatmap"
        );
        assert!(pane.layer_blocked(ChartLayer::Bubbles, quotes).is_some());
        assert!(pane.layer_blocked(ChartLayer::Grid, quotes).is_none());
        // The tape's twins refuse for the same reasons, and say so in the same
        // words: a source with no book has no map to put on the tape either.
        assert!(
            pane.layer_blocked(ChartLayer::TapeHeatmap, quotes)
                .is_some(),
            "a source with no book cannot promise a heatmap on the tape either"
        );
        assert!(
            pane.layer_blocked(ChartLayer::TapeBubbles, quotes)
                .is_some(),
            "nor bubbles where nothing prints a traded quantity"
        );
        assert!(
            pane.layer_blocked(ChartLayer::TapeChart, quotes).is_none(),
            "the band itself is still the trader's to show: it carries the marks \
             and the time axis whatever the source can produce"
        );
        menu_frame(&mut quote_only, Vec::new());
        assert_eq!(
            quote_only.active_tab().flow_pane.layer_menu_rects.len(),
            chart_menu_entries(),
            "an unavailable layer is still listed, just not switchable"
        );
        std::fs::remove_file(&path).ok();
    }

    /// A right-click that lands on a drawing owns a section of the menu:
    /// the object by name, rename, lock, hide, delete — and the lock keeps
    /// guarding the delete there like everywhere else.
    #[test]
    fn the_drawing_section_of_the_menu_acts_on_the_clicked_object() {
        let ctx = egui::Context::default();
        let screen = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(400.0, 700.0));
        let (mut app, _events, _commands, _book) = test_app();

        let rectangle = drawings::DRAWING_TOOLS
            .into_iter()
            .find(|tool| tool.id() == "rectangle")
            .expect("the rectangle tool is registered");
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(1.0, 100.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(5.0, 110.0));
            let id = pane.drawings.items()[0].id;
            // The press half of the gesture, staged: the click resolved the
            // object and seeded the rename buffer, like the canvas path does.
            pane.context_menu_drawing = Some(id);
        }

        let menu_frame = |app: &mut QuantickApp, events: Vec<egui::Event>| {
            with_flow_pane(app, |pane, chrome| {
                let _ = ctx.run(
                    egui::RawInput {
                        screen_rect: Some(screen),
                        events,
                        ..Default::default()
                    },
                    |ctx| {
                        egui::CentralPanel::default()
                            .show(ctx, |ui| pane.draw_layer_menu(ui, chrome));
                    },
                );
            });
        };

        menu_frame(&mut app, Vec::new());
        let labels: Vec<&str> = app
            .active_tab()
            .flow_pane
            .drawing_menu_rects
            .iter()
            .map(|(label, _)| *label)
            .collect();
        assert_eq!(
            labels,
            ["Rename", "Add strategy", "Lock", "Hide", "Delete"],
            "the clicked object owns its section of the menu — rename, the \
             strategy seat, and the guarded actions"
        );

        let click = |rects: &[(&'static str, egui::Rect)], label: &str| {
            let pos = rects
                .iter()
                .find(|(entry, _)| *entry == label)
                .unwrap_or_else(|| panic!("{label} is offered"))
                .1
                .center();
            vec![
                egui::Event::PointerMoved(pos),
                egui::Event::PointerButton {
                    pos,
                    button: egui::PointerButton::Primary,
                    pressed: true,
                    modifiers: egui::Modifiers::default(),
                },
                egui::Event::PointerButton {
                    pos,
                    button: egui::PointerButton::Primary,
                    pressed: false,
                    modifiers: egui::Modifiers::default(),
                },
            ]
        };

        // Locked first: the delete is offered disabled and must do nothing.
        app.active_tab_mut()
            .flow_pane
            .drawings
            .set_locked_at(0, true);
        menu_frame(&mut app, Vec::new());
        let rects = app.active_tab().flow_pane.drawing_menu_rects.clone();
        let events = click(&rects, "Delete");
        menu_frame(&mut app, events);
        assert_eq!(
            app.active_tab().flow_pane.drawings.items().len(),
            1,
            "a locked object never deletes from the menu"
        );

        app.active_tab_mut()
            .flow_pane
            .drawings
            .set_locked_at(0, false);
        menu_frame(&mut app, Vec::new());
        let rects = app.active_tab().flow_pane.drawing_menu_rects.clone();
        let events = click(&rects, "Delete");
        menu_frame(&mut app, events);
        assert!(
            app.active_tab().flow_pane.drawings.items().is_empty(),
            "unlocked, the menu's delete removes the object"
        );
        assert_eq!(
            app.active_tab().flow_pane.context_menu_drawing,
            None,
            "the section lets go of the object it deleted"
        );
    }

    /// The whole semi-automatic loop in one place: a rectangle drawn on the
    /// chart, a force-bar strategy armed on it through the same call the
    /// dialog makes, and the tape walking the operation from trigger to
    /// take profit. The human drew the fence; the machine pulled the
    /// trigger; the simulator answered with fills the tape proves.
    #[test]
    fn an_armed_rectangle_fires_on_the_force_bar_inside_it() {
        fn print(app: &mut QuantickApp, id: &mut u64, price: &str) {
            *id += 1;
            let trade = quantick_engine::Trade {
                agg_id: *id,
                timestamp_ms: 1_700_000_000_000 + *id as i64 * 100,
                price: rust_decimal::Decimal::from_str_exact(price).unwrap(),
                quantity: rust_decimal::Decimal::ONE,
                side: quantick_engine::Side::Buy,
            };
            app.active_tab_mut()
                .ingest_live_trade_at(&trade, trade.timestamp_ms);
        }
        /// One Tick(50) bar: 49 prints at `open`, the fiftieth at `close`.
        fn bar(app: &mut QuantickApp, id: &mut u64, open: &str, close: &str) {
            for _ in 0..49 {
                print(app, id, open);
            }
            print(app, id, close);
        }

        let (mut app, _events, _commands, _book) = test_app();
        let rectangle = drawings::DRAWING_TOOLS
            .into_iter()
            .find(|tool| tool.id() == "rectangle")
            .expect("the rectangle tool is registered");
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(0.0, 100.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(30.0, 110.0));
        }
        let drawing = app.active_tab().flow_pane.drawings.items()[0].id;

        let mut form =
            crate::strategy_presets::StoredPreset::starting_point(quantick_engine::Side::Buy);
        form.window = 3;
        // The fixture's bodies are 4 points; the elephant floor is off so
        // the test exercises the band, not the floor (which has its own).
        form.min_body = "0".to_owned();
        app.arm_strategy_instance(pane::PaneSide::Flow, drawing, &form, "test BF".to_owned())
            .expect("the form compiles and the drawing exists");

        let mut id = 0u64;
        // Three body-1 warmup bars inside the region: quiet, nothing fires.
        bar(&mut app, &mut id, "100", "101");
        bar(&mut app, &mut id, "101", "102");
        bar(&mut app, &mut id, "102", "103");
        assert!(
            app.active_tab().paper.is_flat(),
            "warmup bars must not fire"
        );

        // The force bar: body 4 against an average of (1+1+4)/3 = 2, closing
        // at 107 inside the region. The command queues on the close — the
        // account is no longer clean (the queued entry counts, which is
        // exactly what stops a second instance stacking on the same bar) —
        // but nothing has filled yet.
        bar(&mut app, &mut id, "103", "107");
        assert!(
            !app.active_tab().paper.is_flat(),
            "the queued entry occupies the account before it fills"
        );
        assert!(
            matches!(
                app.active_tab()
                    .flow_pane
                    .strategies
                    .for_drawing(drawing)
                    .expect("instance")
                    .armed
                    .state(),
                quantick_strategy::ArmedState::Fired { .. }
            ),
            "a market order fills on the *next* print, exactly like a hand"
        );
        // …and the next print fills it.
        print(&mut app, &mut id, "107.5");
        assert_eq!(
            app.active_tab()
                .flow_pane
                .strategies
                .for_drawing(drawing)
                .expect("instance")
                .armed
                .state(),
            &quantick_strategy::ArmedState::InPosition,
            "the entry met the tape at the print after the trigger"
        );

        // Take profit = close 107 + 1× range 4 = 111: a print at the level
        // closes the operation.
        print(&mut app, &mut id, "111");
        assert!(
            app.active_tab().paper.is_flat(),
            "the projected take profit closed the operation"
        );

        // The completion bar: the one-shot instance walks to done and holds
        // fire forever after.
        for _ in 0..48 {
            print(&mut app, &mut id, "108");
        }
        let pane = &app.active_tab().flow_pane;
        let instance = pane
            .strategies
            .for_drawing(drawing)
            .expect("the instance still rides the drawing");
        assert_eq!(
            instance.armed.state(),
            &quantick_strategy::ArmedState::Done,
            "one shot per arming: after the round trip the instance is done"
        );
    }

    /// The replay-seek trap: a disarm that reset the ruler (timeline reset,
    /// bar-spec change, market switch) used to leave "re-armed" silently
    /// meaning "warming up for another N bars", so a force bar right after
    /// the seek never fired. The pane's re-arm re-warms the ruler from the
    /// bars the chart already shows; a bare kernel re-arm does not.
    #[test]
    fn rearm_after_a_series_reset_rewarms_the_ruler_from_the_chart() {
        fn print(app: &mut QuantickApp, id: &mut u64, price: &str) {
            *id += 1;
            let trade = quantick_engine::Trade {
                agg_id: *id,
                timestamp_ms: 1_700_000_000_000 + *id as i64 * 100,
                price: rust_decimal::Decimal::from_str_exact(price).unwrap(),
                quantity: rust_decimal::Decimal::ONE,
                side: quantick_engine::Side::Buy,
            };
            app.active_tab_mut()
                .ingest_live_trade_at(&trade, trade.timestamp_ms);
        }
        fn bar(app: &mut QuantickApp, id: &mut u64, open: &str, close: &str) {
            for _ in 0..49 {
                print(app, id, open);
            }
            print(app, id, close);
        }
        fn state_of(
            app: &QuantickApp,
            drawing: drawings::DrawingId,
        ) -> quantick_strategy::ArmedState {
            app.active_tab()
                .flow_pane
                .strategies
                .for_drawing(drawing)
                .expect("instance")
                .armed
                .state()
                .clone()
        }

        let (mut app, _events, _commands, _book) = test_app();
        let rectangle = drawings::DRAWING_TOOLS
            .into_iter()
            .find(|tool| tool.id() == "rectangle")
            .expect("the rectangle tool is registered");
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(0.0, 100.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(60.0, 110.0));
        }
        let drawing = app.active_tab().flow_pane.drawings.items()[0].id;
        let mut form =
            crate::strategy_presets::StoredPreset::starting_point(quantick_engine::Side::Buy);
        form.window = 3;
        form.min_body = "0".to_owned();
        app.arm_strategy_instance(pane::PaneSide::Flow, drawing, &form, "test BF".to_owned())
            .expect("the form compiles and the drawing exists");

        // Two quiet bars on the chart, then the series "changes" under the
        // ruler (the disarm reason a bar-spec change or replay seek names).
        let mut id = 0u64;
        bar(&mut app, &mut id, "100", "101");
        bar(&mut app, &mut id, "101", "102");
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            let _ = pane
                .strategies
                .for_drawing_mut(drawing)
                .expect("instance")
                .armed
                .disarm(quantick_strategy::DisarmReason::BarSpecChanged);
            // The pane's re-arm: kernel re-arm (which resets the ruler)
            // plus the re-warm from the chart's own closed bars.
            pane.rearm_strategy_for_drawing(drawing);
        }
        assert_eq!(
            state_of(&app, drawing),
            quantick_strategy::ArmedState::Armed
        );

        // The very next force bar fires: bodies 1, 1 re-warmed the window,
        // and this bar's body 4 makes ratio 2 on a full window of 3.
        bar(&mut app, &mut id, "102", "106");
        assert!(
            matches!(
                state_of(&app, drawing),
                quantick_strategy::ArmedState::Fired { .. }
            ),
            "the first eligible force bar after the re-arm fires; got {:?}",
            state_of(&app, drawing)
        );
    }

    /// An extended rectangle's region never expires off its right anchor;
    /// an unextended one holds fire past it and the badge names the gate.
    #[test]
    fn extend_right_keeps_the_region_active_past_the_drawn_end() {
        fn print(app: &mut QuantickApp, id: &mut u64, price: &str) {
            *id += 1;
            let trade = quantick_engine::Trade {
                agg_id: *id,
                timestamp_ms: 1_700_000_000_000 + *id as i64 * 100,
                price: rust_decimal::Decimal::from_str_exact(price).unwrap(),
                quantity: rust_decimal::Decimal::ONE,
                side: quantick_engine::Side::Buy,
            };
            app.active_tab_mut()
                .ingest_live_trade_at(&trade, trade.timestamp_ms);
        }
        fn bar(app: &mut QuantickApp, id: &mut u64, open: &str, close: &str) {
            for _ in 0..49 {
                print(app, id, open);
            }
            print(app, id, close);
        }

        let (mut app, _events, _commands, _book) = test_app();
        let rectangle = drawings::DRAWING_TOOLS
            .into_iter()
            .find(|tool| tool.id() == "rectangle")
            .expect("the rectangle tool is registered");
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            // The drawn span ends at slot 2; the force bars land past it.
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(0.0, 100.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(2.0, 110.0));
        }
        let drawing = app.active_tab().flow_pane.drawings.items()[0].id;
        let mut form =
            crate::strategy_presets::StoredPreset::starting_point(quantick_engine::Side::Buy);
        form.window = 3;
        form.min_body = "0".to_owned();
        app.arm_strategy_instance(pane::PaneSide::Flow, drawing, &form, "test BF".to_owned())
            .expect("arming before any bar closed skips the span guard");

        let mut id = 0u64;
        bar(&mut app, &mut id, "100", "101");
        bar(&mut app, &mut id, "101", "102");
        bar(&mut app, &mut id, "102", "103");
        // Slot 3, past the drawn end: a force bar in price, held in time —
        // and the badge says exactly which gate held it.
        bar(&mut app, &mut id, "103", "107");
        {
            let instance = app
                .active_tab()
                .flow_pane
                .strategies
                .for_drawing(drawing)
                .expect("instance");
            assert_eq!(
                instance.armed.state(),
                &quantick_strategy::ArmedState::Armed,
                "past the right anchor the region is inactive"
            );
            assert_eq!(
                instance.armed.status_line(),
                "armed · trigger held: region not active on this bar"
            );
        }

        // Turn on extend right — the drawn band now runs to the chart's
        // edge, and the region with it.
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            let index = pane.drawings.index_of(drawing).expect("drawing lives");
            pane.drawings.items_mut()[index]
                .payload
                .as_any_mut()
                .downcast_mut::<drawings::RectanglePayload>()
                .expect("a rectangle carries a rectangle payload")
                .extend_right = true;
        }
        // Three quiet bars drain the held force bar's body out of the
        // window (back to an average of 1), then a fresh buy force bar
        // closes at 110 — inside the price band, far past the drawn end.
        bar(&mut app, &mut id, "107", "108");
        bar(&mut app, &mut id, "108", "107");
        bar(&mut app, &mut id, "107", "106");
        bar(&mut app, &mut id, "106", "110");
        assert!(
            matches!(
                app.active_tab()
                    .flow_pane
                    .strategies
                    .for_drawing(drawing)
                    .expect("instance")
                    .armed
                    .state(),
                quantick_strategy::ArmedState::Fired { .. }
            ),
            "with extend right on, the region stays active past the drawn end"
        );
    }

    /// Arming a region whose drawn span already ended is refused with the
    /// fix in hand — "armed" over a structurally dead region is the silent
    /// halt the named disarms exist to prevent.
    #[test]
    fn arming_a_region_that_already_ended_is_refused() {
        fn print(app: &mut QuantickApp, id: &mut u64, price: &str) {
            *id += 1;
            let trade = quantick_engine::Trade {
                agg_id: *id,
                timestamp_ms: 1_700_000_000_000 + *id as i64 * 100,
                price: rust_decimal::Decimal::from_str_exact(price).unwrap(),
                quantity: rust_decimal::Decimal::ONE,
                side: quantick_engine::Side::Buy,
            };
            app.active_tab_mut()
                .ingest_live_trade_at(&trade, trade.timestamp_ms);
        }

        let (mut app, _events, _commands, _book) = test_app();
        // Sixteen closed Tick(50) bars, so "the newest bar" is slot 15.
        let mut id = 0u64;
        for _ in 0..16 {
            for _ in 0..50 {
                print(&mut app, &mut id, "100");
            }
        }
        let rectangle = drawings::DRAWING_TOOLS
            .into_iter()
            .find(|tool| tool.id() == "rectangle")
            .expect("the rectangle tool is registered");
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(0.0, 99.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(4.0, 101.0));
        }
        let drawing = app.active_tab().flow_pane.drawings.items()[0].id;
        let form =
            crate::strategy_presets::StoredPreset::starting_point(quantick_engine::Side::Buy);
        let refused = app
            .arm_strategy_instance(pane::PaneSide::Flow, drawing, &form, "dead".to_owned())
            .expect_err("a region ending before the next bar cannot arm");
        assert!(
            refused.contains("extend right"),
            "the refusal hands over the fix: {refused}"
        );

        // The boundary the guard once let through: a right anchor exactly
        // on the newest *closed* bar (slot 15 of 16) still cannot cover
        // the next bar to close (slot 16) — refused, not armed dead.
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(0.0, 99.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(15.0, 101.0));
        }
        let boundary = app.active_tab().flow_pane.drawings.items()[1].id;
        app.arm_strategy_instance(pane::PaneSide::Flow, boundary, &form, "edge".to_owned())
            .expect_err("a span ending on the newest closed bar covers no future bar");
        // One anchored past the next slot arms fine without extend right.
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(0.0, 99.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(16.0, 101.0));
        }
        let alive = app.active_tab().flow_pane.drawings.items()[2].id;
        app.arm_strategy_instance(pane::PaneSide::Flow, alive, &form, "ok".to_owned())
            .expect("a span covering the next slot arms");

        // The same dead drawing with extend right on arms fine.
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            let index = pane.drawings.index_of(drawing).expect("drawing lives");
            pane.drawings.items_mut()[index]
                .payload
                .as_any_mut()
                .downcast_mut::<drawings::RectanglePayload>()
                .expect("a rectangle carries a rectangle payload")
                .extend_right = true;
        }
        app.arm_strategy_instance(pane::PaneSide::Flow, drawing, &form, "live".to_owned())
            .expect("extend right keeps the region alive, so arming is honest");
    }

    /// Delete-all (and by the same sweep, undo/redo) must not leave a
    /// resting bot order behind when the drawings vanish outside the
    /// per-drawing removal funnel.
    #[test]
    fn delete_all_sweeps_the_armed_instances_pending_entries() {
        fn print(app: &mut QuantickApp, id: &mut u64, price: &str) {
            *id += 1;
            let trade = quantick_engine::Trade {
                agg_id: *id,
                timestamp_ms: 1_700_000_000_000 + *id as i64 * 100,
                price: rust_decimal::Decimal::from_str_exact(price).unwrap(),
                quantity: rust_decimal::Decimal::ONE,
                side: quantick_engine::Side::Buy,
            };
            app.active_tab_mut()
                .ingest_live_trade_at(&trade, trade.timestamp_ms);
        }
        fn bar(app: &mut QuantickApp, id: &mut u64, open: &str, close: &str) {
            for _ in 0..49 {
                print(app, id, open);
            }
            print(app, id, close);
        }

        let (mut app, _events, _commands, _book) = test_app();
        let rectangle = drawings::DRAWING_TOOLS
            .into_iter()
            .find(|tool| tool.id() == "rectangle")
            .expect("the rectangle tool is registered");
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(0.0, 105.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(30.0, 115.0));
        }
        let drawing = app.active_tab().flow_pane.drawings.items()[0].id;
        let mut form =
            crate::strategy_presets::StoredPreset::starting_point(quantick_engine::Side::Sell);
        form.window = 3;
        form.min_body = "0".to_owned();
        form.on_break = "retest_limit".to_owned();
        app.arm_strategy_instance(pane::PaneSide::Flow, drawing, &form, "BF".to_owned())
            .expect("the form compiles");
        let mut id = 0u64;
        bar(&mut app, &mut id, "110", "109");
        bar(&mut app, &mut id, "109", "108");
        bar(&mut app, &mut id, "108", "104");
        assert_eq!(
            app.active_tab().paper.working_orders().len(),
            1,
            "the retest limit rests"
        );

        // Delete every drawing the way the manager's button does, then run
        // the same-frame sweep + drain the tab applies.
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            pane.drawings.delete_all();
            pane.sweep_strategy_orphans();
        }
        app.active_tab_mut().apply_strategy_cleanup();
        assert!(
            app.active_tab().paper.working_orders().is_empty(),
            "no resting bot order outlives its badge"
        );
        assert!(app.active_tab().flow_pane.strategies.is_empty());
    }

    /// The user's retest flow end to end in the app: a sell preset with the
    /// retest option armed on a region, a force bar cutting below it, the
    /// limit resting at the cut edge — then the tape reaching the target
    /// first, the order removing itself, and the badge saying so.
    #[test]
    fn a_cut_with_the_retest_preset_rests_a_limit_and_cancels_at_the_target() {
        fn print(app: &mut QuantickApp, id: &mut u64, price: &str) {
            *id += 1;
            let trade = quantick_engine::Trade {
                agg_id: *id,
                timestamp_ms: 1_700_000_000_000 + *id as i64 * 100,
                price: rust_decimal::Decimal::from_str_exact(price).unwrap(),
                quantity: rust_decimal::Decimal::ONE,
                side: quantick_engine::Side::Buy,
            };
            app.active_tab_mut()
                .ingest_live_trade_at(&trade, trade.timestamp_ms);
        }
        fn bar(app: &mut QuantickApp, id: &mut u64, open: &str, close: &str) {
            for _ in 0..49 {
                print(app, id, open);
            }
            print(app, id, close);
        }

        let (mut app, _events, _commands, _book) = test_app();
        let rectangle = drawings::DRAWING_TOOLS
            .into_iter()
            .find(|tool| tool.id() == "rectangle")
            .expect("the rectangle tool is registered");
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(0.0, 105.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(30.0, 115.0));
        }
        let drawing = app.active_tab().flow_pane.drawings.items()[0].id;
        let mut form =
            crate::strategy_presets::StoredPreset::starting_point(quantick_engine::Side::Sell);
        form.window = 3;
        form.min_body = "0".to_owned();
        form.on_break = "retest_limit".to_owned();
        app.arm_strategy_instance(pane::PaneSide::Flow, drawing, &form, "BF retest".to_owned())
            .expect("the retest form compiles");

        let mut id = 0u64;
        bar(&mut app, &mut id, "110", "109");
        bar(&mut app, &mut id, "109", "108");
        // Body 4 over average (1+1+4)/3 = 2: force, closing below the 105
        // edge. The bar's range is 4 (prints at 108 and 104): TP 100.
        bar(&mut app, &mut id, "108", "104");
        {
            let tab = app.active_tab();
            assert_eq!(
                tab.paper.working_orders().len(),
                1,
                "the retest limit rests at the cut edge"
            );
            let instance = tab
                .flow_pane
                .strategies
                .for_drawing(drawing)
                .expect("instance");
            assert!(
                matches!(
                    instance.armed.state(),
                    quantick_strategy::ArmedState::Fired { retest: true, .. }
                ),
                "the instance narrates a resting retest, got {:?}",
                instance.armed.state()
            );
        }

        // The tape walks straight down through the projected target (100):
        // the order removes itself — no fill, no trade — and the one-shot
        // instance stops with the reason on the badge.
        print(&mut app, &mut id, "100");
        let tab = app.active_tab();
        assert!(
            tab.paper.working_orders().is_empty(),
            "the target print removed the resting limit"
        );
        assert!(tab.paper.is_flat(), "no trade happened");
        let instance = tab
            .flow_pane
            .strategies
            .for_drawing(drawing)
            .expect("instance");
        assert_eq!(
            instance.armed.state(),
            &quantick_strategy::ArmedState::Disarmed {
                reason: quantick_strategy::DisarmReason::TargetBeforeRetest
            }
        );
        assert_eq!(instance.armed.status_line(), "target hit before retest");
    }

    /// The resting retest limit never trades against a hand: if the trader
    /// opens a manual position while the order rests, the fill moment
    /// stands the order down — the trader's position and bracket survive
    /// untouched, and the badge says why the bot declined.
    #[test]
    fn a_resting_retest_limit_stands_down_over_a_manual_position() {
        fn print(app: &mut QuantickApp, id: &mut u64, price: &str) {
            *id += 1;
            let trade = quantick_engine::Trade {
                agg_id: *id,
                timestamp_ms: 1_700_000_000_000 + *id as i64 * 100,
                price: rust_decimal::Decimal::from_str_exact(price).unwrap(),
                quantity: rust_decimal::Decimal::ONE,
                side: quantick_engine::Side::Buy,
            };
            app.active_tab_mut()
                .ingest_live_trade_at(&trade, trade.timestamp_ms);
        }
        fn bar(app: &mut QuantickApp, id: &mut u64, open: &str, close: &str) {
            for _ in 0..49 {
                print(app, id, open);
            }
            print(app, id, close);
        }

        let (mut app, _events, _commands, _book) = test_app();
        let rectangle = drawings::DRAWING_TOOLS
            .into_iter()
            .find(|tool| tool.id() == "rectangle")
            .expect("the rectangle tool is registered");
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(0.0, 105.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(30.0, 115.0));
        }
        let drawing = app.active_tab().flow_pane.drawings.items()[0].id;
        let mut form =
            crate::strategy_presets::StoredPreset::starting_point(quantick_engine::Side::Sell);
        form.window = 3;
        form.min_body = "0".to_owned();
        form.on_break = "retest_limit".to_owned();
        app.arm_strategy_instance(pane::PaneSide::Flow, drawing, &form, "BF retest".to_owned())
            .expect("the retest form compiles");

        let mut id = 0u64;
        bar(&mut app, &mut id, "110", "109");
        bar(&mut app, &mut id, "109", "108");
        bar(&mut app, &mut id, "108", "104");
        assert_eq!(app.active_tab().paper.working_orders().len(), 1);

        // The trader buys at market while the bot's limit rests.
        app.active_tab_mut().paper.apply_sim_command_for_tests(
            quantick_sim::Command::PlaceMarket {
                side: quantick_engine::Side::Buy,
                quantity: Decimal::ONE,
                bracket: quantick_sim::Bracket::none(),
            },
        );
        print(&mut app, &mut id, "104");
        assert!(
            app.active_tab().paper.position_summary().is_some(),
            "the manual long filled"
        );

        // The tape returns to the edge: the bot's fill moment finds the
        // account occupied and stands down instead of netting the trader's
        // long closed.
        print(&mut app, &mut id, "105");
        let tab = app.active_tab();
        assert!(
            tab.paper.working_orders().is_empty(),
            "the bot's order stood down"
        );
        assert!(
            tab.paper.position_summary().is_some(),
            "the trader's long survives untouched"
        );
        let instance = tab
            .flow_pane
            .strategies
            .for_drawing(drawing)
            .expect("instance");
        assert_eq!(
            instance.armed.state(),
            &quantick_strategy::ArmedState::Disarmed {
                reason: quantick_strategy::DisarmReason::AccountOccupied
            }
        );
        assert_eq!(instance.armed.status_line(), "stood down — account busy");
    }

    /// Two instances co-triggered by one closed bar must not stack: the
    /// first one's *queued* entry already occupies the account, so the
    /// second holds fire — "at most one live operation per chart" is a
    /// property of the gate, not of luck.
    #[test]
    fn co_triggered_instances_do_not_stack_orders() {
        fn print(app: &mut QuantickApp, id: &mut u64, price: &str) {
            *id += 1;
            let trade = quantick_engine::Trade {
                agg_id: *id,
                timestamp_ms: 1_700_000_000_000 + *id as i64 * 100,
                price: rust_decimal::Decimal::from_str_exact(price).unwrap(),
                quantity: rust_decimal::Decimal::ONE,
                side: quantick_engine::Side::Buy,
            };
            app.active_tab_mut()
                .ingest_live_trade_at(&trade, trade.timestamp_ms);
        }
        fn bar(app: &mut QuantickApp, id: &mut u64, open: &str, close: &str) {
            for _ in 0..49 {
                print(app, id, open);
            }
            print(app, id, close);
        }

        let (mut app, _events, _commands, _book) = test_app();
        let rectangle = drawings::DRAWING_TOOLS
            .into_iter()
            .find(|tool| tool.id() == drawings::RECTANGLE_TOOL_ID)
            .expect("the rectangle tool is registered");
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(0.0, 100.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(30.0, 110.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(0.0, 95.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(30.0, 115.0));
        }
        let first = app.active_tab().flow_pane.drawings.items()[0].id;
        let second = app.active_tab().flow_pane.drawings.items()[1].id;
        let mut form =
            crate::strategy_presets::StoredPreset::starting_point(quantick_engine::Side::Buy);
        form.window = 3;
        form.min_body = "0".to_owned();
        app.arm_strategy_instance(pane::PaneSide::Flow, first, &form, "a".to_owned())
            .expect("arms");
        app.arm_strategy_instance(pane::PaneSide::Flow, second, &form, "b".to_owned())
            .expect("arms");

        let mut id = 0u64;
        bar(&mut app, &mut id, "100", "101");
        bar(&mut app, &mut id, "101", "102");
        bar(&mut app, &mut id, "102", "103");
        // One force bar inside both regions: both triggers say fire, the
        // gate lets exactly one through.
        bar(&mut app, &mut id, "103", "107");
        let fired = app
            .active_tab()
            .flow_pane
            .strategies
            .instances
            .iter()
            .filter(|instance| {
                matches!(
                    instance.armed.state(),
                    quantick_strategy::ArmedState::Fired { .. }
                )
            })
            .count();
        assert_eq!(fired, 1, "the queued entry blocks the second instance");
    }

    /// The safety sweeps are wired, not just written: a rebuilt timeline
    /// disarms every instance with the reset's own reason on the badge.
    #[test]
    fn a_timeline_reset_disarms_the_armed_instances_by_name() {
        let (mut app, _events, _commands, _book) = test_app();
        let rectangle = drawings::DRAWING_TOOLS
            .into_iter()
            .find(|tool| tool.id() == "rectangle")
            .expect("the rectangle tool is registered");
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(0.0, 100.0));
            pane.drawings
                .place(rectangle, drawings::ChartPoint::at(30.0, 110.0));
        }
        let drawing = app.active_tab().flow_pane.drawings.items()[0].id;
        let form =
            crate::strategy_presets::StoredPreset::starting_point(quantick_engine::Side::Sell);
        app.arm_strategy_instance(pane::PaneSide::Flow, drawing, &form, "test".to_owned())
            .expect("arms");

        app.active_tab_mut().reset_market_state();

        let pane = &app.active_tab().flow_pane;
        let instance = pane
            .strategies
            .for_drawing(drawing)
            .expect("still attached");
        assert_eq!(
            instance.armed.state(),
            &quantick_strategy::ArmedState::Disarmed {
                reason: quantick_strategy::DisarmReason::TimelineReset
            },
            "a judgement armed on the old timeline must not carry into the new one"
        );
    }

    /// The two panes open different menus, so the scripted right-click has to
    /// name one — and refuse anything it does not recognise, since opening the
    /// wrong pane's menu photographs a defect that is not there.
    #[test]
    fn the_context_menu_hook_names_a_pane_or_opens_nothing() {
        assert_eq!(
            ContextMenuPane::from_env_value("tape"),
            Some(ContextMenuPane::Tape)
        );
        assert_eq!(
            ContextMenuPane::from_env_value(" LANE "),
            Some(ContextMenuPane::Tape)
        );
        assert_eq!(
            ContextMenuPane::from_env_value("chart"),
            Some(ContextMenuPane::Chart)
        );
        assert_eq!(
            ContextMenuPane::from_env_value("candles"),
            Some(ContextMenuPane::Chart)
        );
        for refused in ["", "1", "true", "both", "pane"] {
            assert_eq!(ContextMenuPane::from_env_value(refused), None, "{refused}");
        }
    }

    /// The scripted click lands on the canvas of the pane it names, and asks
    /// for nothing that is not on screen: no draw yet means no geometry, and a
    /// canvas with no tape has no tape menu to open.
    #[test]
    fn the_scripted_click_lands_on_the_pane_it_names() {
        let (mut app, _events, _commands, _book) = test_app();
        assert_eq!(
            app.scripted_context_menu_pos(ContextMenuPane::Tape),
            None,
            "nothing has drawn yet, so there is no geometry to click"
        );

        let rect = egui::Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1000.0, 400.0));
        {
            let pane = &mut app.active_tab_mut().flow_pane;
            pane.last_chart_rect = Some(rect);
            pane.last_lane_divider_x = Some(700.0);
        }
        let tape = app
            .scripted_context_menu_pos(ContextMenuPane::Tape)
            .expect("a drawn tape can be clicked");
        assert!(tape.x > 700.0 && tape.x < 1000.0, "{tape:?}");
        let chart = app
            .scripted_context_menu_pos(ContextMenuPane::Chart)
            .expect("and so can the candles");
        assert!(chart.x > 0.0 && chart.x < 700.0, "{chart:?}");
        assert!(rect.contains(tape) && rect.contains(chart));

        // No lane: the candles still answer, the tape has nothing to open.
        app.active_tab_mut().flow_pane.last_lane_divider_x = None;
        assert_eq!(app.scripted_context_menu_pos(ContextMenuPane::Tape), None);
        assert!(
            app.scripted_context_menu_pos(ContextMenuPane::Chart)
                .is_some()
        );
    }

    /// The tape's window hook reads what a human would type, and refuses
    /// everything else rather than guessing — a capture of the wrong state is
    /// worse than a capture of the default one.
    #[test]
    fn the_tape_window_hook_reads_durations_and_refuses_nonsense() {
        assert_eq!(parse_tape_window("auto"), Some(LaneWindow::default()));
        assert_eq!(parse_tape_window("  AUTO "), Some(LaneWindow::default()));
        for (typed, ms) in [
            ("15s", 15_000),
            ("90s", 90_000),
            ("1min", 60_000),
            ("2min", 120_000),
            ("2m", 120_000),
            ("1.5min", 90_000),
            ("120000ms", 120_000),
            ("120000", 120_000),
        ] {
            assert_eq!(
                parse_tape_window(typed),
                Some(LaneWindow::Fixed { ms }),
                "{typed}"
            );
        }
        for refused in ["", "soon", "2 hours", "-5s", "0", "0s", "NaN", "infs"] {
            assert_eq!(parse_tape_window(refused), None, "{refused}");
        }
    }

    /// A right-click on the tape configures the tape. The candles' layers do
    /// not vanish with it — they move one submenu away — because the tape is
    /// also where a trader right-clicks to trade, and a menu that answered
    /// only for the tape would take order entry and the drawing tools with it.
    #[test]
    fn a_right_click_on_the_tape_configures_the_tape_without_losing_the_chart() {
        let dir = std::env::temp_dir().join(format!("quantick-tape-menu-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("scratch dir");
        let path = dir.join("chart-layers.toml");
        let _ = std::fs::remove_file(&path);

        let ctx = egui::Context::default();
        let screen = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(400.0, 700.0));
        let (mut app, _events, _commands, _book) = test_app();
        app.chart_layers_path = path.clone();

        let menu_frame = |app: &mut QuantickApp, on_tape: bool| {
            with_flow_pane(app, |pane, chrome| {
                pane.aim_context_menu_at_tape(on_tape);
                let _ = ctx.run(
                    egui::RawInput {
                        screen_rect: Some(screen),
                        ..Default::default()
                    },
                    |ctx| {
                        egui::CentralPanel::default()
                            .show(ctx, |ui| pane.draw_layer_menu(ui, chrome));
                    },
                );
            });
        };

        // The candles' own menu is exactly the menu it always was.
        menu_frame(&mut app, false);
        assert_eq!(
            app.active_tab().flow_pane.layer_menu_rects.len(),
            chart_menu_entries(),
            "a click on the candles still lists every chart layer up front"
        );

        // The tape's menu answers for the tape: its own three switches at the
        // top level, and the chart's behind the submenu button rather than
        // laid out beside them.
        menu_frame(&mut app, true);
        let tape_menu = app.active_tab().flow_pane.layer_menu_rects.clone();
        assert_eq!(
            tape_menu.len(),
            tape_menu_entries(),
            "the tape's own switches are what a click on the tape lists"
        );
        assert!(
            tape_menu.iter().all(|(layer, _)| layer.on_tape()),
            "and none of the candles' are laid out beside them"
        );
        for layer in [
            ChartLayer::TapeChart,
            ChartLayer::TapeHeatmap,
            ChartLayer::TapeBubbles,
        ] {
            assert!(
                tape_menu.iter().any(|(entry, _)| *entry == layer),
                "{} is reachable from the tape's own menu",
                layer.id()
            );
        }

        // And back: aiming at the candles restores the full list, so the two
        // menus cannot leak into each other across frames.
        menu_frame(&mut app, false);
        assert_eq!(
            app.active_tab().flow_pane.layer_menu_rects.len(),
            chart_menu_entries()
        );
        std::fs::remove_file(&path).ok();
    }

    /// §11 keeps the tape on the flow pane, so the time pane's menu says the
    /// flow layers are drawn elsewhere instead of offering dead switches.
    #[test]
    fn the_time_pane_offers_the_flow_layers_as_drawn_elsewhere() {
        let (app, _events, _commands, _book) = test_app();
        let capabilities = app.active_tab().capabilities(&app.config);
        let time = ChartPane::time(99, 60_000);
        for layer in [
            ChartLayer::Heatmap,
            ChartLayer::Bubbles,
            ChartLayer::LiveStrip,
            ChartLayer::LaneMarks,
            ChartLayer::DepthGaps,
        ] {
            assert_eq!(
                time.layer_blocked(layer, capabilities),
                Some("the order-flow layers are drawn on the flow pane"),
                "{} has no machinery on a time pane",
                layer.id()
            );
            assert!(!time.layer_visible(layer, &app.style));
        }
        for layer in [
            ChartLayer::Grid,
            ChartLayer::LastPrice,
            ChartLayer::Crosshair,
            ChartLayer::Drawings,
        ] {
            assert!(time.layer_blocked(layer, capabilities).is_none());
        }
    }

    /// A switched-off layer really stops painting.
    ///
    /// The switches above only prove the *state* moved; this one draws a real
    /// chart and counts the shapes, so a gate someone forgets to place
    /// (or later deletes) shows up as a menu entry that changes nothing.
    #[test]
    fn a_hidden_layer_paints_nothing() {
        let ctx = egui::Context::default();
        let screen = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(900.0, 600.0));
        let (mut app, _commands) = app_with_history(120);
        let under_test = [
            ChartLayer::LastPrice,
            ChartLayer::BackfillDivider,
            ChartLayer::Crosshair,
        ];

        // Shape totals may only move because one of the three synchronous
        // gates under test moved. A flow pane normally asks the order-flow
        // worker for a projection; that frame can legitimately arrive between
        // any two draws and add unrelated shapes. Hide every other layer so
        // this fixture never starts that asynchronous projection pipeline.
        for layer in ChartLayer::ALL {
            switch_layer(&mut app, layer, under_test.contains(&layer));
        }
        // The crosshair is a mode: it paints under a pointer, with its own tool
        // armed. Both are set here so the layer has something to switch off.
        app.toolrail.arm(Tool::Crosshair);

        let shapes = |app: &mut QuantickApp| -> usize {
            with_flow_pane(app, |pane, chrome| {
                let output = ctx.run(
                    egui::RawInput {
                        screen_rect: Some(screen),
                        ..Default::default()
                    },
                    |ctx| {
                        egui::CentralPanel::default().show(ctx, |ui| {
                            let area = ui.available_rect_before_wrap();
                            pane.hover_pos = Some(area.center());
                            pane.draw_chart(ui.painter(), area, chrome);
                        });
                    },
                );
                output.shapes.len()
            })
        };

        // One frame to settle: plot geometry and the price range are computed
        // by a draw and read by the next one, so the first frame is
        // not yet the chart this test is counting. **Every** measurement gets
        // that frame, not just the baseline — an exact shape count taken one
        // frame after a switch is counting a chart still converging on its
        // price range, and the asymmetry made this test fail on a loaded CI
        // runner and pass on the next attempt.
        let settled = |app: &mut QuantickApp| {
            let _ = shapes(app);
            shapes(app)
        };
        let all_on = settled(&mut app);
        for layer in under_test {
            switch_layer(&mut app, layer, false);
            let off = settled(&mut app);
            assert!(
                off < all_on,
                "{} kept painting after it was switched off ({off} shapes vs {all_on})",
                layer.id()
            );
            switch_layer(&mut app, layer, true);
            assert_eq!(
                settled(&mut app),
                all_on,
                "{} did not come back exactly as it was",
                layer.id()
            );
        }
    }

    /// The replay seek, end to end: a round trip closes on the tape, the
    /// source rebuilds the timeline under it — the trade survives (it
    /// happened), the bars do not — and the marks wait for the rebuilt tape
    /// to reach the fills instead of stacking on whichever bar sits at the
    /// edge and accumulating there as the replay runs on.
    #[test]
    fn a_rebuilt_timeline_does_not_stack_old_marks_on_its_edge() {
        let ctx = egui::Context::default();
        let screen = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(900.0, 600.0));
        let (mut app, evt_tx, _cmd_rx, _book_tx) = test_app();
        let dir = std::env::temp_dir().join(format!(
            "quantick-trade-paint-rebuild-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        app.active_tab_mut().paper.redirect_history_dir(dir.clone());
        // A round trip: bought on print 4, closed on print 6.
        evt_tx
            .try_send(FeedEvent::Backfilled(vec![trade(2)]))
            .unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        app.apply_toolbar_action(ToolbarAction::PaperBuy);
        evt_tx.try_send(FeedEvent::Live(trade(4))).unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        app.apply_toolbar_action(ToolbarAction::PaperClose);
        evt_tx.try_send(FeedEvent::Live(trade(6))).unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        assert_eq!(
            app.active_tab().paper.session_trades().len(),
            1,
            "one closed round trip to paint"
        );

        // Convex polygons only — the entry triangles and the exit diamonds.
        // Counting the whole frame would ride on the price range still
        // easing after the rebuild, and a gridline more or less between two
        // measurements is not what this test is about.
        let marks = |app: &mut QuantickApp| -> usize {
            with_flow_pane(app, |pane, chrome| {
                let output = ctx.run(
                    egui::RawInput {
                        screen_rect: Some(screen),
                        ..Default::default()
                    },
                    |ctx| {
                        egui::CentralPanel::default().show(ctx, |ui| {
                            let area = ui.available_rect_before_wrap();
                            pane.draw_chart(ui.painter(), area, chrome);
                        });
                    },
                );
                output
                    .shapes
                    .iter()
                    .filter(|shape| matches!(shape.shape, egui::epaint::Shape::Path(_)))
                    .count()
            })
        };
        // Frames to settle the ranges a draw computes for the next one.
        let settled = |app: &mut QuantickApp| {
            for _ in 0..3 {
                let _ = marks(app);
            }
            marks(app)
        };

        // The seek: the bars go, the round trip stays, and the tape refills
        // from a print older than both of its fills.
        app.active_tab_mut().reset_market_state();
        evt_tx
            .try_send(FeedEvent::Backfilled(vec![trade(0)]))
            .unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        assert_eq!(
            app.active_tab().paper.session_trades().len(),
            1,
            "the trade happened; the rebuild does not un-happen it"
        );

        let ahead_of_the_tape = settled(&mut app);
        switch_layer(&mut app, ChartLayer::TradePaint, false);
        let marks_off = settled(&mut app);
        assert_eq!(
            ahead_of_the_tape, marks_off,
            "a fill the rebuilt tape has not reached still painted: {ahead_of_the_tape} vs {marks_off}"
        );
        switch_layer(&mut app, ChartLayer::TradePaint, true);

        // The tape runs on past both fills; now the marks have their bars.
        for id in [2, 4, 6] {
            evt_tx.try_send(FeedEvent::Live(trade(id))).unwrap();
        }
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        let covered = settled(&mut app);
        switch_layer(&mut app, ChartLayer::TradePaint, false);
        let covered_off = settled(&mut app);
        assert_eq!(
            covered - covered_off,
            2,
            "the marks did not come back once the tape covered them: {covered} vs {covered_off}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A one-print recording on disk, read back through the replay crate's
    /// own loader — the cheapest honest recording a test can hand a tab.
    fn recording_at(dir: &std::path::Path) -> quantick_replay::Session {
        std::fs::create_dir_all(dir).expect("the scratch folder is writable");
        let mut text =
            quantick_replay::format::write_header(&quantick_replay::format::WriteHeader {
                symbol: "TESTUSDT".to_owned(),
                timezone: quantick_replay::UtcOffset::UTC,
                side_source: "venue".to_owned(),
                source: None,
            });
        quantick_replay::format::write_trade(
            &mut text,
            &trade(2),
            None,
            quantick_replay::UtcOffset::UTC,
        );
        let path = dir.join("20260316.csv");
        std::fs::write(&path, text).expect("the recording is written");
        quantick_replay::Session::load(&path, quantick_replay::ParseOptions::default())
            .expect("the recording this test just wrote parses")
    }

    /// With a recording playing and the round trips closed, the scripted
    /// seek presses Restart once — and only once, whatever the next frame
    /// finds.
    #[test]
    fn the_scripted_replay_restart_seeks_once_the_trades_are_in() {
        let (mut app, evt_tx, mut cmd_rx, _book_tx) = test_app();
        let dir = std::env::temp_dir().join(format!(
            "quantick-replay-restart-hook-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        let journal = dir.join("journal");
        app.active_tab_mut().paper.redirect_history_dir(journal);
        app.active_tab_mut().replay = Some(feed::ReplayLink::for_test(recording_at(&dir)));
        while cmd_rx.try_recv().is_ok() {}
        app.pending_replay_restart = Some(1);

        // No round trip yet: the hook waits rather than seeking an empty
        // ledger, which would photograph nothing it exists to show.
        app.apply_replay_restart();
        assert_eq!(
            app.pending_replay_restart,
            Some(1),
            "the seek fired before a trade had closed"
        );

        // One round trip, then the seek.
        evt_tx
            .try_send(FeedEvent::Backfilled(vec![trade(2)]))
            .unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        app.apply_toolbar_action(ToolbarAction::PaperBuy);
        evt_tx.try_send(FeedEvent::Live(trade(4))).unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        app.apply_toolbar_action(ToolbarAction::PaperClose);
        evt_tx.try_send(FeedEvent::Live(trade(6))).unwrap();
        app.active_tab_mut().drain_feed_with_clock(|| 0);
        assert_eq!(app.active_tab().paper.session_trades().len(), 1);

        app.apply_replay_restart();
        assert_eq!(app.pending_replay_restart, None, "the hook is consumed");
        assert!(
            matches!(
                cmd_rx.try_recv(),
                Ok(FeedCommand::Replay(ReplayControl::Restart))
            ),
            "the transport was asked for its own Restart"
        );

        // A second frame asks for nothing: an env var is a request for this
        // run, not a standing rule.
        app.apply_replay_restart();
        assert!(cmd_rx.try_recv().is_err(), "the seek repeated itself");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The scripted seek needs a recording under it: on a live feed there is
    /// no timeline to restart, so the hook waits instead of firing into one
    /// — and the transport channel stays empty.
    #[test]
    fn the_scripted_replay_restart_waits_for_a_recording() {
        let (mut app, _evt_tx, mut cmd_rx, _book_tx) = test_app();
        // Whatever the startup already asked the feed for is not the
        // subject; only what the hook adds after it is.
        while cmd_rx.try_recv().is_ok() {}
        app.pending_replay_restart = Some(1);
        app.apply_replay_restart();
        assert_eq!(
            app.pending_replay_restart,
            Some(1),
            "a live feed has no timeline to seek"
        );
        assert!(
            cmd_rx.try_recv().is_err(),
            "and nothing was asked of the transport"
        );
    }

    /// The closed-trade marks obey their own switch: a closed round trip
    /// paints marks and a connector, `closed trade marks` off erases them,
    /// and the live paper layer is untouched either way — hiding history
